/* ─── COMPONENT ────────────────────────────────────────────────────── */

// Audio file map — place MP3s in /public/audio/
// Files: owner-00.mp3 through owner-08.mp3
const OWNER_AUDIO = [
  "/audio/owner-00.mp3",
  "/audio/owner-01.mp3",
  "/audio/owner-02.mp3",
  "/audio/owner-03.mp3",
  "/audio/owner-04.mp3",
  "/audio/owner-05.mp3",
  "/audio/owner-06.mp3",
  "/audio/owner-07.mp3",
  "/audio/owner-08.mp3",
];

export default function StormChecksOwnerOnboarding() {
  const [screen, setScreen] = useState(0);
  const [caseIdx, setCaseIdx] = useState(0);
  const [objIdx, setObjIdx] = useState(0);
  const [visible, setVisible] = useState(true);
  const [muted, setMuted] = useState(false);
  const mainRef = useRef(null);
  const audioRef = useRef(null);
  const mutedRef = useRef(false);
  const LAST = 8;

  // Keep mutedRef in sync so the go() callback always reads current value
  useEffect(() => { mutedRef.current = muted; }, [muted]);

  useEffect(() => {
    const link = document.createElement("link");
    link.href = "https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap";
    link.rel = "stylesheet";
    document.head.appendChild(link);
    const s = document.createElement("style");
    s.id = "sc-owner-style";
    s.textContent = `
      *{box-sizing:border-box;margin:0;padding:0}
      body{background:#0B1F33;overscroll-behavior:none}
      .intercom-launcher,.intercom-namespace .intercom-lightweight-app{display:none!important}
      ::-webkit-scrollbar{width:3px}
      ::-webkit-scrollbar-thumb{background:#C99700;border-radius:2px}
    `;
    if (!document.getElementById("sc-owner-style")) document.head.appendChild(s);
    return () => {
      document.getElementById("sc-owner-style")?.remove();
      if (audioRef.current) { audioRef.current.pause(); audioRef.current = null; }
    };
  }, []);

  useEffect(() => {
    const fn = (e) => {
      if (e.key === "ArrowRight" || e.key === "ArrowDown") go(screen + 1);
      if (e.key === "ArrowLeft"  || e.key === "ArrowUp")   go(screen - 1);
    };
    window.addEventListener("keydown", fn);
    return () => window.removeEventListener("keydown", fn);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screen]);

  const playAudio = useCallback((idx) => {
    if (audioRef.current) { audioRef.current.pause(); audioRef.current.src = ""; }
    const src = OWNER_AUDIO[idx];
    if (!src) return;
    const audio = new Audio(src);
    audio.volume = 1;
    audio.muted = mutedRef.current;
    audioRef.current = audio;
    audio.play().catch(() => {}); // swallow autoplay policy errors silently
  }, []);

  const go = useCallback((idx) => {
    if (idx < 0 || idx > LAST) return;
    setVisible(false);
    setTimeout(() => {
      setScreen(idx);
      setVisible(true);
      mainRef.current?.scrollTo({ top: 0, behavior: "smooth" });
      playAudio(idx);
    }, 190);
  }, [playAudio]);

  const toggleMute = () => {
    const next = !muted;
    setMuted(next);
    mutedRef.current = next;
    if (audioRef.current) audioRef.current.muted = next;
  };

  const pct = screen === 0 ? 0 : screen >= LAST ? 100 : Math.round((screen / (LAST - 1)) * 100);

  return (
    <div style={S.root}>
      <div style={S.gridBg} />

      {/* ── Header ── */}
      <header style={S.header}>
        <Logo />
        {screen > 0 && (
          <div style={S.progressTrack}>
            <div style={{ ...S.progressBar, width: `${pct}%` }} />
          </div>
        )}
        {screen > 0 && screen < LAST && (
          <span style={S.counter}>
            <b style={{ color: "#C99700" }}>{String(screen).padStart(2,"0")}</b>
            <span style={{ color: "rgba(255,255,255,0.2)" }}> / {String(LAST - 1).padStart(2,"0")}</span>
          </span>
        )}
        {screen > 0 && (
          <button onClick={toggleMute} style={S.muteBtn} aria-label={muted ? "Unmute narration" : "Mute narration"}>
            {muted ? "🔇" : "🔊"}
          </button>
        )}
      </header>

      {/* ── Content ── */}
      <main
        ref={mainRef}
        style={{
          ...S.main,
          opacity: visible ? 1 : 0,
          transform: visible ? "translateY(0)" : "translateY(8px)",
        }}
      >
        {screen === 0 && <Welcome onStart={() => go(1)} />}
        {screen === 1 && <Problem />}
        {screen === 2 && <HowItWorks />}
        {screen === 3 && <YourSteps />}
        {screen === 4 && <Fees />}
        {screen === 5 && <CaseStudies idx={caseIdx} setIdx={setCaseIdx} />}
        {screen === 6 && <Objections idx={objIdx} setIdx={setObjIdx} />}
        {screen === 7 && <Timeline />}
        {screen === 8 && <CTA />}
      </main>

      {/* ── Bottom Nav ── */}
      {screen > 0 && screen < LAST && (
        <nav style={S.nav}>
          <button
            onClick={() => go(screen - 1)}
            style={{ ...S.navBtn, opacity: screen > 1 ? 1 : 0.25 }}
            disabled={screen <= 1}
          >←</button>
          <div style={S.dots}>
            {Array.from({ length: LAST - 1 }, (_, i) => (
              <button key={i} onClick={() => go(i + 1)} style={{
                ...S.dot,
                width: i + 1 === screen ? 20 : 6,
                background: i + 1 === screen ? "#C99700" : i + 1 < screen ? "rgba(201,151,0,0.35)" : "rgba(255,255,255,0.15)",
              }} />
            ))}
          </div>
          <button onClick={() => go(screen + 1)} style={S.navBtn}>
            {screen === LAST - 1 ? "Finish" : "→"}
          </button>
        </nav>
      )}
    </div>
  );
}

/* ─── SCREENS ───────────────────────────────────────────────────────── */

function Welcome({ onStart }) {
  return (
    <div style={{ textAlign:"center", maxWidth:500 }}>
      <Pill>PROPERTY OWNER BRIEFING</Pill>
      <h1 style={S.h1}>Find out what your<br /><Em>building is hiding.</Em></h1>
      <p style={S.lead}>StormChecks is a forensic building consultancy. We find hidden storm damage using meteorological data and licensed engineering — then document it for insurance recovery at no upfront cost.</p>
      <p style={{ ...S.lead, fontSize:14, opacity:0.7, marginBottom:36 }}>What we do, what it costs, what you'll need to do. About 4 minutes.</p>
      <button onClick={onStart} style={S.cta}>Start Briefing →</button>
      <p style={S.hint}>Arrow keys or tap dots to navigate</p>
    </div>
  );
}

function Problem() {
  return (
    <Wrap>
      <Tag>The Problem</Tag>
      <h2 style={S.h2}>Storm damage is invisible.<br /><Em>Most owners never find it.</Em></h2>
      <p style={{ ...S.body, marginBottom:20 }}>Hail fractures membranes. Wind displaces cladding. HVAC units absorb impacts that never show as leaks — until the filing window closes and the money stays with your carrier. Maintenance teams and standard inspections aren't trained to find this. Forensic engineers are.</p>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8, margin:"20px 0" }}>
        {[
          { n:"$10–15", l:"per sq ft found consistently" },
          { n:"$400K",  l:"average recovery per property" },
          { n:"$10B+",  l:"in damage assessed by our team" },
          { n:"$0",     l:"upfront cost to the owner" },
        ].map(s => (
          <div key={s.n} style={S.statCard}>
            <div style={S.statNum}>{s.n}</div>
            <div style={S.statLbl}>{s.l}</div>
          </div>
        ))}
      </div>
      <Note>
        <b style={{ color:"#C99700" }}>Why insurance doesn't fix this automatically:</b>{" "}
        Carriers don't send inspectors. They pay claims when documentation is submitted. No documentation = no claim = damage stays unrecovered — permanently after the filing window closes.
      </Note>
    </Wrap>
  );
}

function HowItWorks() {
  const items = [
    { n:"01", t:"Meteorological Analysis", d:"We pull the precise storm history for your property coordinates — hail size, wind speed, storm path, and date — for the past 2 years. This determines what hit your building and when." },
    { n:"02", t:"Forensic Engineering",    d:"Licensed Professional Engineers inspect on-site. They identify hail fractures, membrane compression, cladding impact, and HVAC damage using methods standard inspections don't use." },
    { n:"03", t:"Expert File",             d:"120+ page forensic documentation package: timestamped photography, structural analysis, causation narrative, and Xactimate cost estimates in carrier-recognized format." },
    { n:"04", t:"Public Adjuster Handoff", d:"We connect you with a vetted PA who files and negotiates the claim using our Expert File as the evidentiary foundation. We don't negotiate — they do." },
  ];
  return (
    <Wrap>
      <Tag>How It Works</Tag>
      <h2 style={S.h2}>Four disciplines.<br /><Em>One Expert File.</Em></h2>
      <p style={{ ...S.body, marginBottom:20 }}>StormChecks is not a contractor, not a public adjuster, not an insurance advocate. We find and document damage. The PA recovers it.</p>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
        {items.map(d => (
          <div key={d.n} style={S.card}>
            <div style={S.cardNum}>{d.n}</div>
            <div style={S.cardTitle}>{d.t}</div>
            <div style={S.cardDesc}>{d.d}</div>
          </div>
        ))}
      </div>
    </Wrap>
  );
}

